// TODO(T05): dedupe with lib/tools/result.ts (T05 owns it; minimal copy until it lands on main).
export type ToolErrorKind =
  | "timeout"
  | "http"
  | "rate_limited"
  | "blocked"
  | "not_found"
  | "invalid_input"
  | "parse";

export type ToolError = { kind: ToolErrorKind; message: string; retryable: boolean };

export type ToolResult<T> = { ok: true; data: T } | { ok: false; error: ToolError };

export const toolOk = <T>(data: T): ToolResult<T> => ({ ok: true, data });

export const toolErr = <T>(
  kind: ToolErrorKind,
  message: string,
  retryable: boolean,
): ToolResult<T> => ({ ok: false, error: { kind, message, retryable } });
import { toolErr, type ToolResult } from "./domain-result";

// TODO(T05): replace with the shared retry/backoff helper in lib/tools/result.ts once it lands.
export type GetDeps = {
  fetch?: typeof fetch;
  sleep?: (ms: number) => Promise<void>;
};

export type RawResponse = { status: number; text: string };

const BACKOFF_MS = 500;
const MAX_BODY_CHARS = 100_000;

/** GET with one retry on timeout, 5xx, or 429 (Retry-After honored up to 3 s). Never throws. */
export async function getWithRetry(
  url: string,
  opts: { timeoutMs: number; headers?: Record<string, string> } & GetDeps,
): Promise<ToolResult<RawResponse>> {
  const doFetch = opts.fetch ?? fetch;
  const sleep = opts.sleep ?? ((ms: number) => new Promise<void>((r) => setTimeout(r, ms)));
  let last: ToolResult<RawResponse> = toolErr("http", "no attempt made", true);
  for (let attempt = 0; attempt < 2; attempt++) {
    let waitMs = BACKOFF_MS;
    try {
      const res = await doFetch(url, { headers: opts.headers, signal: AbortSignal.timeout(opts.timeoutMs) });
      if (res.status === 429) {
        const ra = Number(res.headers.get("retry-after"));
        if (Number.isFinite(ra) && ra > 0) waitMs = Math.min(ra * 1000, 3000);
        last = toolErr("rate_limited", "rate limited (429)", true);
      } else if (res.status >= 500) {
        last = toolErr("http", `upstream error ${res.status}`, true);
      } else {
        return { ok: true, data: { status: res.status, text: (await res.text()).slice(0, MAX_BODY_CHARS) } };
      }
    } catch (e) {
      const timedOut = e instanceof DOMException && (e.name === "TimeoutError" || e.name === "AbortError");
      last = timedOut
        ? toolErr("timeout", `request timed out after ${opts.timeoutMs} ms`, true)
        : toolErr("http", "network error", true);
    }
    if (attempt === 0) await sleep(waitMs);
  }
  return last;
}
import { parse } from "tldts";
import { z } from "zod";
import { toolErr, toolOk, type ToolResult } from "./domain-result";
import { getWithRetry, type GetDeps } from "./json-get";

export const RdapInput = z.object({ domain: z.string().min(1).max(253) });

export type RdapData = {
  registrableDomain: string;
  registered: boolean;
  createdAt?: string;
  ageDays?: number;
  registrar?: string;
};

const RdapBody = z.object({
  events: z.array(z.object({ eventAction: z.string(), eventDate: z.string() })).optional(),
  entities: z
    .array(z.object({ roles: z.array(z.string()).optional(), vcardArray: z.tuple([z.string(), z.array(z.array(z.unknown()))]).optional() }))
    .optional(),
});

const registrarName = (body: z.infer<typeof RdapBody>): string | undefined => {
  const ent = body.entities?.find((e) => e.roles?.includes("registrar"));
  const fn = ent?.vcardArray?.[1].find((p) => p[0] === "fn");
  return typeof fn?.[3] === "string" ? fn[3] : undefined;
};

/** A failure here is never suspicious on its own (SPEC §7): it returns an error, not registered:false. */
export async function rdapDomain(
  input: z.infer<typeof RdapInput>,
  deps: GetDeps & { now?: () => Date } = {},
): Promise<ToolResult<RdapData>> {
  const parsed = RdapInput.safeParse(input);
  const registrableDomain = parsed.success ? parse(parsed.data.domain.trim().toLowerCase()).domain : null;
  if (!registrableDomain) return toolErr("invalid_input", "domain is not valid", false);

  const res = await getWithRetry(`https://rdap.org/domain/${registrableDomain}`, {
    timeoutMs: 5000,
    headers: { accept: "application/rdap+json" },
    ...deps,
  });
  if (!res.ok) return res;
  if (res.data.status === 404) return toolOk({ registrableDomain, registered: false });
  if (res.data.status !== 200) return toolErr("http", `RDAP returned ${res.data.status}`, false);

  let body: z.infer<typeof RdapBody>;
  try {
    body = RdapBody.parse(JSON.parse(res.data.text));
  } catch {
    return toolErr("parse", "RDAP response was not valid JSON", false);
  }
  const createdAt = body.events?.find((e) => e.eventAction === "registration")?.eventDate;
  const created = createdAt ? Date.parse(createdAt) : NaN;
  const now = (deps.now ?? (() => new Date()))();
  return toolOk({
    registrableDomain,
    registered: true,
    ...(createdAt && !Number.isNaN(created) ? { createdAt, ageDays: Math.floor((now.getTime() - created) / 86_400_000) } : {}),
    ...(registrarName(body) ? { registrar: registrarName(body) } : {}),
